    onKeyboardInteractive?(
      cb: (request: {
        requestId: string;
        sessionId: string;
        hostId?: string;
        name: string;
        instructions: string;
        prompts: Array<{ prompt: string; echo: boolean }>;
        hostname: string;
        savedPassword?: string | null;
        /** When false, UI must not offer saving the response as the host password. */
        allowSavePassword?: boolean;
