export type ShrinkFinding =
  | { suspicious: false }
  | {
      suspicious: true;
      reason: 'bulk-shrink' | 'large-shrink';
      entityType: CloudSyncPayloadEntityKey;
      baseCount: number;
      outgoingCount: number;
      lost: number;
      /** True when the comparison reference was the current remote (base was null). */
      viaRemote?: boolean;
    };

const CHECKED_ENTITIES = CLOUD_SYNC_PAYLOAD_ENTITY_KEYS;

type CheckedEntityType = CloudSyncPayloadEntityKey;

const BULK_SHRINK_RATIO = 0.5;
const BULK_SHRINK_MIN_ABSOLUTE = 3;
const LARGE_SHRINK_ABSOLUTE = 10;

function countOf(p: SyncPayload, key: CheckedEntityType): number {
  const v = p[key];
  return Array.isArray(v) ? v.length : 0;
}

export function detectSuspiciousShrink(
  outgoing: SyncPayload,
  base: SyncPayload | null,
  remote?: SyncPayload | null,
): ShrinkFinding {
  // Fall back to the current remote when we have no stored base — a null base
  // happens on first sync, after unlock key re-derivation, or when the base
  // blob failed to decrypt. Without this fallback, a degraded/empty local
  // payload would be admitted unconditionally and could overwrite populated
  // remote data (#779). We only use `remote` when `base` is unavailable so
  // legitimate resurrections (device that legitimately grew past an older
  // remote snapshot) remain unaffected.
  const reference = base ?? remote ?? null;
  const viaRemote = !base && !!remote;
  if (!reference) return { suspicious: false };

  for (const entityType of CHECKED_ENTITIES) {
    const baseCount = countOf(reference, entityType);
    const outgoingCount = countOf(outgoing, entityType);
    const lost = baseCount - outgoingCount;
    if (lost <= 0) continue;

    // groupConfigs often hold startup commands / host appearance for only one
    // or two folders. A hydration race that uploads hosts + groupConfigs:[]
    // falls below the bulk/ratio gates (#2757). Only flag this entity — wiping
    // the last snippet/note/etc. while hosts remain stays a normal delete.
    // Fully empty outgoing snapshots remain allowed as real deletions.
    if (
      entityType === 'groupConfigs'
      && outgoingCount === 0
      && baseCount > 0
      && CHECKED_ENTITIES.some((other) => other !== entityType && countOf(outgoing, other) > 0)
    ) {
      return {
        suspicious: true,
        reason: lost >= LARGE_SHRINK_ABSOLUTE ? 'large-shrink' : 'bulk-shrink',
        entityType,
        baseCount,
        outgoingCount,
        lost,
        ...(viaRemote ? { viaRemote: true } : {}),
      };
    }

    if (lost >= LARGE_SHRINK_ABSOLUTE) {
      return {
        suspicious: true,
        reason: 'large-shrink',
        entityType,
        baseCount,
        outgoingCount,
        lost,
        ...(viaRemote ? { viaRemote: true } : {}),
      };
    }

    if (baseCount > 0 && lost / baseCount >= BULK_SHRINK_RATIO && lost >= BULK_SHRINK_MIN_ABSOLUTE) {
      return {
        suspicious: true,
        reason: 'bulk-shrink',
        entityType,
        baseCount,
        outgoingCount,
        lost,
        ...(viaRemote ? { viaRemote: true } : {}),
      };
    }
  }

  return { suspicious: false };
}

/**
 * Three-Way Merge for Cloud Sync Payloads
 *
 * Implements a Git-style three-way merge using a stored "base" snapshot
 * (the last successfully synced payload) to detect per-entity changes
 * on both the local and remote sides.
 *
 * Algorithm:
 *   For each entity (identified by `id`):
 *     - Only in local  → local addition  → keep
 *     - Only in remote → remote addition → keep
 *     - In base, removed locally   → local deletion  → remove (unless remote modified)
 *     - In base, removed remotely  → remote deletion → remove (unless local modified)
 *     - Modified only locally      → keep local version
 *     - Modified only remotely     → keep remote version
 *     - Modified on both sides     → prefer local (conflict logged)
 *
 * When no base is available (first sync), falls back to a set-union
 * merge by entity ID, preferring local for duplicates.
 */

import { carryForwardSyncDeletions, getDeletedEntityIds } from './syncReliability';
import type { CloudSyncPayloadEntityKey, SyncPayload } from './sync';
import { mergePluginSyncSidecarsThreeWay } from './pluginSyncSidecar';

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

interface MergeSummary {
  added: { local: number; remote: number };
  deleted: { local: number; remote: number };
  modified: { local: number; remote: number; conflicts: number };
}

interface MergeResult {
  payload: SyncPayload;
  /** True when both sides modified the same entity (resolved by preferring local) */
  hadConflicts: boolean;
  summary: MergeSummary;
}

const OPTIONAL_ENTITY_KEYS = new Set<CloudSyncPayloadEntityKey>([
  'identities',
  'proxyProfiles',
  'snippetPackages',
  'notes',
  'noteGroups',
  'portForwardingRules',
  'groupConfigs',
]);

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Deterministic JSON string for content comparison.
 * Sorts object keys to avoid false diffs from key ordering.
 */
function fingerprint(value: unknown): string {
  return JSON.stringify(value, (_key, v) => {
    if (v && typeof v === 'object' && !Array.isArray(v)) {
      return Object.keys(v).sort().reduce<Record<string, unknown>>((acc, k) => {
        acc[k] = (v as Record<string, unknown>)[k];
        return acc;
      }, {});
    }
    return v;
  });
}

function entityArray<T>(
  payload: SyncPayload,
  key: CloudSyncPayloadEntityKey,
  fallback: T[],
): T[] {
  if (
    OPTIONAL_ENTITY_KEYS.has(key)
    && !Object.prototype.hasOwnProperty.call(payload, key)
  ) {
    return fallback;
  }
  const value = payload[key];
  return Array.isArray(value) ? value as T[] : [];
}

// ---------------------------------------------------------------------------
// Entity-array merge (hosts, keys, identities, snippets, etc.)
// ---------------------------------------------------------------------------

interface EntityMergeResult<T> {
  merged: T[];
  conflicts: number;
  added: { local: number; remote: number };
  deleted: { local: number; remote: number };
  modified: { local: number; remote: number };
}

function mergeEntityArrays<T extends { id: string }>(
  base: T[],
  local: T[],
  remote: T[],
  tombstones?: { local: Set<string>; remote: Set<string> },
): EntityMergeResult<T> {
  const baseMap = new Map(base.map((e) => [e.id, e]));
  const localMap = new Map(local.map((e) => [e.id, e]));
  const remoteMap = new Map(remote.map((e) => [e.id, e]));

  const allIds = new Set([
    ...baseMap.keys(),
    ...localMap.keys(),
    ...remoteMap.keys(),
  ]);

  const merged: T[] = [];
  let conflicts = 0;
  const added = { local: 0, remote: 0 };
  const deleted = { local: 0, remote: 0 };
  const modified = { local: 0, remote: 0 };

  for (const id of allIds) {
    const baseItem = baseMap.get(id);
    const localItem = localMap.get(id);
    const remoteItem = remoteMap.get(id);

    const inBase = baseItem !== undefined;
    const inLocal = localItem !== undefined;
    const inRemote = remoteItem !== undefined;

    if (!inBase && inLocal && !inRemote && tombstones?.remote.has(id)) {
      // Remote explicitly records this entity as deleted. When no base is
      // available, this tombstone is the only durable signal that absence is
      // intentional rather than an old client omitting the entity.
      deleted.remote++;
    } else if (!inBase && !inLocal && inRemote && tombstones?.local.has(id)) {
      deleted.local++;
    } else if (!inBase && inLocal && !inRemote) {
      // Local addition
      merged.push(localItem);
      added.local++;
    } else if (!inBase && !inLocal && inRemote) {
      // Remote addition
      merged.push(remoteItem);
      added.remote++;
    } else if (!inBase && inLocal && inRemote) {
      // Both added same ID — prefer local
      merged.push(localItem);
      if (fingerprint(localItem) !== fingerprint(remoteItem)) {
        conflicts++;
      }
    } else if (inBase && inLocal && inRemote) {
      // Exists in all three — compare changes
      const localChanged = fingerprint(localItem) !== fingerprint(baseItem);
      const remoteChanged = fingerprint(remoteItem) !== fingerprint(baseItem);

      if (!localChanged && !remoteChanged) {
        merged.push(baseItem);
      } else if (localChanged && !remoteChanged) {
        merged.push(localItem);
        modified.local++;
      } else if (!localChanged && remoteChanged) {
        merged.push(remoteItem);
        modified.remote++;
      } else {
        // Both changed — prefer local
        merged.push(localItem);
        if (fingerprint(localItem) !== fingerprint(remoteItem)) {
          conflicts++;
        }
        modified.local++;
        modified.remote++;
      }
    } else if (inBase && !inLocal && inRemote) {
      // Local deleted
      const remoteChanged = fingerprint(remoteItem) !== fingerprint(baseItem);
      if (remoteChanged) {
        // Remote modified + local deleted → keep modification (safer)
        merged.push(remoteItem);
        conflicts++;
      } else {
        deleted.local++;
      }
    } else if (inBase && inLocal && !inRemote) {
      // Remote deleted
      const localChanged = fingerprint(localItem) !== fingerprint(baseItem);
      if (localChanged) {
        // Local modified + remote deleted → keep modification (safer)
        merged.push(localItem);
        conflicts++;
      } else {
        deleted.remote++;
      }
    }
    // inBase && !inLocal && !inRemote → both deleted → gone
  }

  return { merged, conflicts, added, deleted, modified };
}

// ---------------------------------------------------------------------------
// String-array merge (customGroups, snippetPackages)
// ---------------------------------------------------------------------------

function mergeStringArrays(
  base: string[],
  local: string[],
  remote: string[],
  tombstones?: { local: Set<string>; remote: Set<string> },
): string[] {
  const baseSet = new Set(base);
  const localSet = new Set(local);
  const remoteSet = new Set(remote);

  const result = new Set<string>();

  // Start with base items, then apply additions/deletions
  const allValues = new Set([...baseSet, ...localSet, ...remoteSet]);

  for (const value of allValues) {
    const inBase = baseSet.has(value);
    const inLocal = localSet.has(value);
    const inRemote = remoteSet.has(value);

    if (!inBase && inLocal && !inRemote && tombstones?.remote.has(value)) {
      // Remote tombstone wins over a stale local value when no base exists.
    } else if (!inBase && !inLocal && inRemote && tombstones?.local.has(value)) {
      // Local tombstone wins over a stale remote value when no base exists.
    } else if (!inBase) {
      // Addition — keep if either side added it
      if (inLocal || inRemote) result.add(value);
    } else {
      // Was in base — keep unless both sides deleted
      const localDeleted = !inLocal;
      const remoteDeleted = !inRemote;
      if (localDeleted && remoteDeleted) {
        // Both deleted — gone
      } else if (localDeleted || remoteDeleted) {
        // Only one side deleted — honour the deletion
        // (If the other side didn't touch it, it's still in their set from base)
      } else {
        result.add(value);
      }
    }
  }

  return [...result];
}

// ---------------------------------------------------------------------------
// Settings merge (flat key-value)
// ---------------------------------------------------------------------------

type SettingsObj = NonNullable<SyncPayload['settings']>;

/** Check if an array contains objects with `id` fields (for entity merge). */
function isIdArray(arr: unknown[]): boolean {
  return arr.length > 0 && typeof arr[0] === 'object' && arr[0] !== null && 'id' in arr[0];
}

/** Treat an explicit empty object as a reset marker during the first cloud merge. */
function isEmptyPlainObject(value: unknown): value is Record<string, never> {
  return value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value) &&
    Object.keys(value).length === 0;
}

/** Recursively merge two plain objects against a base using three-way logic. */
function mergeSettingsDeep(
  base: Record<string, unknown>,
  local: Record<string, unknown>,
  remote: Record<string, unknown>,
  preferRemoteOnConflict: boolean,
): Record<string, unknown> {
  const allKeys = new Set([
    ...Object.keys(base),
    ...Object.keys(local),
    ...Object.keys(remote),
  ]);
  const merged: Record<string, unknown> = {};
  for (const key of allKeys) {
    const bVal = base[key];
    const lVal = local[key];
    const rVal = remote[key];
    const lChanged = fingerprint(lVal) !== fingerprint(bVal);
    const rChanged = fingerprint(rVal) !== fingerprint(bVal);

    if (!lChanged && !rChanged) {
      if (bVal !== undefined) merged[key] = bVal;
    } else if (lChanged && !rChanged) {
      if (lVal !== undefined) merged[key] = lVal;
    } else if (!lChanged && rChanged) {
      if (rVal !== undefined) merged[key] = rVal;
    } else {
      // Both changed — recurse if both are plain objects, else prefer local
      if (
        lVal && rVal &&
        typeof lVal === 'object' && !Array.isArray(lVal) &&
        typeof rVal === 'object' && !Array.isArray(rVal)
      ) {
        merged[key] = preferRemoteOnConflict && isEmptyPlainObject(rVal)
          ? rVal
          : mergeSettingsDeep(
            (bVal && typeof bVal === 'object' && !Array.isArray(bVal) ? bVal : {}) as Record<string, unknown>,
            lVal as Record<string, unknown>,
            rVal as Record<string, unknown>,
            preferRemoteOnConflict,
          );
      } else if (
        preferRemoteOnConflict &&
        Array.isArray(lVal) && Array.isArray(rVal) &&
        (isIdArray(lVal) || isIdArray(rVal) || isIdArray(Array.isArray(bVal) ? bVal as unknown[] : []))
      ) {
        const bArr = Array.isArray(bVal) ? bVal as Array<{ id: string }> : [];
        const result = mergeEntityArrays(
          bArr,
          rVal as Array<{ id: string }>,
          lVal as Array<{ id: string }>,
        );
        merged[key] = result.merged;
      } else if (preferRemoteOnConflict && rVal !== undefined) {
        merged[key] = rVal;
      } else if (lVal !== undefined) {
        merged[key] = lVal;
      }
    }
  }
  return merged;
}

function mergeSettings(
  base: SettingsObj | undefined,
  local: SettingsObj | undefined,
  remote: SettingsObj | undefined,
  preferRemoteOnConflict: boolean,
): SettingsObj | undefined {
  if (!local && !remote) return undefined;
  if (!local) return remote;
  if (!remote) return local;

  const b = base ?? {};
  const allKeys = new Set([
    ...Object.keys(b),
    ...Object.keys(local),
    ...Object.keys(remote),
  ]);

  const merged: Record<string, unknown> = {};

  for (const key of allKeys) {
    const bVal = (b as Record<string, unknown>)[key];
    const lVal = (local as Record<string, unknown>)[key];
    const rVal = (remote as Record<string, unknown>)[key];

    const lChanged = fingerprint(lVal) !== fingerprint(bVal);
    const rChanged = fingerprint(rVal) !== fingerprint(bVal);

    if (!lChanged && !rChanged) {
      if (bVal !== undefined) merged[key] = bVal;
    } else if (lChanged && !rChanged) {
      if (lVal !== undefined) merged[key] = lVal;
    } else if (!lChanged && rChanged) {
      if (rVal !== undefined) merged[key] = rVal;
    } else {
      // Both changed — deep merge if both are plain objects, else prefer local
      if (
        lVal && rVal &&
        typeof lVal === 'object' && !Array.isArray(lVal) &&
        typeof rVal === 'object' && !Array.isArray(rVal)
      ) {
        merged[key] = preferRemoteOnConflict && isEmptyPlainObject(rVal)
          ? rVal
          : mergeSettingsDeep(
            (bVal && typeof bVal === 'object' && !Array.isArray(bVal) ? bVal : {}) as Record<string, unknown>,
            lVal as Record<string, unknown>,
            rVal as Record<string, unknown>,
            preferRemoteOnConflict,
          );
      } else if (
        Array.isArray(lVal) && Array.isArray(rVal) &&
        (isIdArray(lVal) || isIdArray(rVal) || isIdArray(Array.isArray(bVal) ? bVal as unknown[] : []))
      ) {
        // Array of objects with `id` (e.g. customTerminalThemes) — entity merge
        const bArr = Array.isArray(bVal) ? bVal as Array<{ id: string }> : [];
        const preferred = preferRemoteOnConflict ? rVal : lVal;
        const other = preferRemoteOnConflict ? lVal : rVal;
        const result = mergeEntityArrays(
          bArr,
          preferred as Array<{ id: string }>,
          other as Array<{ id: string }>,
        );
        merged[key] = result.merged;
      } else if (preferRemoteOnConflict && rVal !== undefined) {
        merged[key] = rVal;
      } else if (lVal !== undefined) {
        merged[key] = lVal;
      }
    }
  }

  return Object.keys(merged).length > 0 ? (merged as SettingsObj) : undefined;
}

// ---------------------------------------------------------------------------
// Main merge function
// ---------------------------------------------------------------------------

/**
 * Three-way merge of sync payloads.
 *
 * @param base  - The last successfully synced payload (null if unavailable)
 * @param local - The current device's data
 * @param remote - The other device's data (downloaded from cloud)
 */
export function mergeSyncPayloads(
  base: SyncPayload | null,
  local: SyncPayload,
  remote: SyncPayload,
): MergeResult {
  const emptyBase: SyncPayload = {
    hosts: [],
    keys: [],
    identities: [],
    proxyProfiles: [],
    snippets: [],
    customGroups: [],
    snippetPackages: [],
    notes: [],
    noteGroups: [],
    portForwardingRules: [],
    settings: undefined,
    syncedAt: 0,
  };
  const b = base ?? emptyBase;

  const summary: MergeSummary = {
    added: { local: 0, remote: 0 },
    deleted: { local: 0, remote: 0 },
    modified: { local: 0, remote: 0, conflicts: 0 },
  };
  const tombstones = (entityType: CloudSyncPayloadEntityKey) => ({
    local: getDeletedEntityIds(local, entityType),
    remote: getDeletedEntityIds(remote, entityType),
  });

  // Merge each entity type
  const hosts = mergeEntityArrays(b.hosts ?? [], local.hosts ?? [], remote.hosts ?? [], tombstones('hosts'));
  const keys = mergeEntityArrays(b.keys ?? [], local.keys ?? [], remote.keys ?? [], tombstones('keys'));
  const baseIdentities = b.identities ?? [];
  const identities = mergeEntityArrays(
    baseIdentities,
    entityArray(local, 'identities', baseIdentities),
    entityArray(remote, 'identities', baseIdentities),
    tombstones('identities'),
  );
  const baseProxyProfiles = b.proxyProfiles ?? [];
  const proxyProfiles = mergeEntityArrays(
    baseProxyProfiles,
    entityArray(local, 'proxyProfiles', baseProxyProfiles),
    entityArray(remote, 'proxyProfiles', baseProxyProfiles),
    tombstones('proxyProfiles'),
  );
  const snippets = mergeEntityArrays(b.snippets ?? [], local.snippets ?? [], remote.snippets ?? [], tombstones('snippets'));
  const baseNotes = b.notes ?? [];
  const notes = mergeEntityArrays(
    baseNotes,
    entityArray(local, 'notes', baseNotes),
    entityArray(remote, 'notes', baseNotes),
    tombstones('notes'),
  );
  const basePortForwardingRules = b.portForwardingRules ?? [];
  const portForwardingRules = mergeEntityArrays(
    basePortForwardingRules,
    entityArray(local, 'portForwardingRules', basePortForwardingRules),
    entityArray(remote, 'portForwardingRules', basePortForwardingRules),
    tombstones('portForwardingRules'),
  );

  // Merge group configs (keyed by path — wrap with virtual id for entity merge)
  type GCWithId = import('./models').GroupConfig & { id: string };
  const wrapGC = (arr: import('./models').GroupConfig[] | undefined): GCWithId[] =>
    (arr ?? []).map(gc => ({ ...gc, id: gc.path }));
  const unwrapGC = (arr: GCWithId[]): import('./models').GroupConfig[] =>
    arr.map(({ id: _id, ...rest }) => rest as import('./models').GroupConfig);
  const baseGroupConfigs = b.groupConfigs ?? [];
  const groupConfigsResult = mergeEntityArrays(
    wrapGC(baseGroupConfigs),
    wrapGC(entityArray(local, 'groupConfigs', baseGroupConfigs)),
    wrapGC(entityArray(remote, 'groupConfigs', baseGroupConfigs)),
    tombstones('groupConfigs'),
  );

  // Aggregate stats
  const entityResults: Pick<EntityMergeResult<unknown>, 'added' | 'deleted' | 'modified' | 'conflicts'>[] =
    [hosts, keys, identities, proxyProfiles, snippets, notes, portForwardingRules, groupConfigsResult];
  for (const r of entityResults) {
    summary.added.local += r.added.local;
    summary.added.remote += r.added.remote;
    summary.deleted.local += r.deleted.local;
    summary.deleted.remote += r.deleted.remote;
    summary.modified.local += r.modified.local;
    summary.modified.remote += r.modified.remote;
    summary.modified.conflicts += r.conflicts;
  }

  // Merge string arrays
  const customGroups = mergeStringArrays(
    b.customGroups ?? [],
    local.customGroups ?? [],
    remote.customGroups ?? [],
    tombstones('customGroups'),
  );
  const baseSnippetPackages = b.snippetPackages ?? [];
  const snippetPackages = mergeStringArrays(
    baseSnippetPackages,
    entityArray<string>(local, 'snippetPackages', baseSnippetPackages),
    entityArray<string>(remote, 'snippetPackages', baseSnippetPackages),
    tombstones('snippetPackages'),
  );
  const baseNoteGroups = b.noteGroups ?? [];
  const noteGroups = mergeStringArrays(
    baseNoteGroups,
    entityArray<string>(local, 'noteGroups', baseNoteGroups),
    entityArray<string>(remote, 'noteGroups', baseNoteGroups),
    tombstones('noteGroups'),
  );

  // Merge settings
  // With no trusted base, the remote payload represents the established
  // cloud replica while a newly installed client has already persisted its
  // initial defaults. Treating both as additions and preferring local would
  // keep those defaults and make settings appear not to sync at all. Prefer
  // the cloud value only for same-field conflicts on this first merge; fields
  // present on just one side are still preserved. Once a base exists, retain
  // the existing local-wins three-way conflict policy.
  const settings = mergeSettings(
    b.settings,
    local.settings,
    remote.settings,
    base === null,
  );

  // Deduplicate global SFTP bookmarks by path (IDs are random per device)
  if (settings?.sftpGlobalBookmarks && settings.sftpGlobalBookmarks.length > 0) {
    const seenPaths = new Set<string>();
    settings.sftpGlobalBookmarks = settings.sftpGlobalBookmarks.filter((bm) => {
      if (seenPaths.has(bm.path)) return false;
      seenPaths.add(bm.path);
      return true;
    });
  }

  const groupConfigs = unwrapGC(groupConfigsResult.merged);

  // Plugin sidecars: three-way merge so local resets propagate and baselines
  // from missing plugins are preserved. An *omitted* pluginSidecars field means
  // legacy/unsupported (treat as base for that side). Explicit { entries: [] }
  // is an authoritative wipe.
  const baseHasSidecars = Object.prototype.hasOwnProperty.call(b, 'pluginSidecars');
  const localHasSidecars = Object.prototype.hasOwnProperty.call(local, 'pluginSidecars');
  const remoteHasSidecars = Object.prototype.hasOwnProperty.call(remote, 'pluginSidecars');
  const baseSidecars = Array.isArray(b.pluginSidecars?.entries) ? b.pluginSidecars.entries : [];
  const localSidecars = localHasSidecars
    ? (Array.isArray(local.pluginSidecars?.entries) ? local.pluginSidecars.entries : [])
    : baseSidecars;
  const remoteSidecars = remoteHasSidecars
    ? (Array.isArray(remote.pluginSidecars?.entries) ? remote.pluginSidecars.entries : [])
    : baseSidecars;
  const mergedSidecarEntries = mergePluginSyncSidecarsThreeWay({
    base: baseSidecars,
    local: localSidecars,
    remote: remoteSidecars,
  });
  // Emit the field when any side explicitly carried it (including empty reset).
  const anySideHadPluginSidecars = baseHasSidecars || localHasSidecars || remoteHasSidecars;

  const payload: SyncPayload = carryForwardSyncDeletions({
    hosts: hosts.merged,
    keys: keys.merged,
    identities: identities.merged,
    proxyProfiles: proxyProfiles.merged,
    snippets: snippets.merged,
    customGroups,
    snippetPackages,
    notes: notes.merged,
    noteGroups,
    portForwardingRules: portForwardingRules.merged,
    groupConfigs,
    settings,
    ...(mergedSidecarEntries.length > 0 || anySideHadPluginSidecars
      ? { pluginSidecars: { version: 1 as const, entries: mergedSidecarEntries } }
      : {}),
    syncedAt: Date.now(),
  }, [local, remote]);

  return {
    payload,
    hadConflicts: summary.modified.conflicts > 0,
    summary,
  };
}

import {
  CLOUD_SYNC_PAYLOAD_ENTITY_KEYS,
  type CloudSyncPayloadEntityKey,
  type SyncChangeEntityKey,
  type SyncChangeSummary,
  type SyncDeletionRecord,
  type SyncEntityChangeCounts,
  type SyncPayload,
  type SyncReliabilityMeta,
} from './sync';

type EntityValue = { id?: string; path?: string } | string;

export const SYNC_SNAPSHOT_LIMIT = 5;

const EMPTY_COUNTS = (): SyncEntityChangeCounts => ({
  added: { local: 0, remote: 0 },
  modified: { local: 0, remote: 0 },
  deleted: { local: 0, remote: 0 },
});
const OPTIONAL_ENTITY_KEYS = new Set<CloudSyncPayloadEntityKey>([
  'identities',
  'proxyProfiles',
  'snippetPackages',
  'portForwardingRules',
  'groupConfigs',
]);

function fingerprint(value: unknown): string {
  return JSON.stringify(value, (_key, v) => {
    if (v && typeof v === 'object' && !Array.isArray(v)) {
      return Object.keys(v).sort().reduce<Record<string, unknown>>((acc, k) => {
        acc[k] = (v as Record<string, unknown>)[k];
        return acc;
      }, {});
    }
    return v;
  });
}

function entityId(value: EntityValue): string {
  return typeof value === 'string' ? value : value.id ?? value.path ?? '';
}

function entityMap(values: unknown): Map<string, EntityValue> {
  if (!Array.isArray(values)) return new Map();
  return new Map(
    values
      .filter((value): value is EntityValue =>
        typeof value === 'string'
        || (
          Boolean(value)
          && typeof value === 'object'
          && (
            typeof (value as { id?: unknown }).id === 'string'
            || typeof (value as { path?: unknown }).path === 'string'
          )
        ),
      )
      .map((value) => [entityId(value), value]),
  );
}

function payloadValues(
  payload: SyncPayload,
  entityType: CloudSyncPayloadEntityKey,
  base?: SyncPayload,
): unknown {
  if (
    base
    && OPTIONAL_ENTITY_KEYS.has(entityType)
    && !Object.prototype.hasOwnProperty.call(payload, entityType)
  ) {
    return base[entityType];
  }
  return payload[entityType];
}

function incrementEntity(
  summary: SyncChangeSummary,
  entityType: SyncChangeEntityKey,
  updater: (counts: SyncEntityChangeCounts) => void,
): void {
  const counts = summary.byEntity[entityType] ?? EMPTY_COUNTS();
  updater(counts);
  summary.byEntity[entityType] = counts;
}

function recordEntityChanges(
  summary: SyncChangeSummary,
  entityType: CloudSyncPayloadEntityKey,
  baseValues: unknown,
  localValues: unknown,
  remoteValues?: unknown,
): void {
  const base = entityMap(baseValues);
  const local = entityMap(localValues);
  const remote = remoteValues === undefined ? null : entityMap(remoteValues);
  const ids = new Set([
    ...base.keys(),
    ...local.keys(),
    ...(remote ? remote.keys() : []),
  ]);

  for (const id of ids) {
    const baseItem = base.get(id);
    const localItem = local.get(id);
    const remoteItem = remote?.get(id);
    const localAdded = !baseItem && Boolean(localItem);
    const localDeleted = Boolean(baseItem) && !localItem;
    const localModified = Boolean(baseItem && localItem)
      && fingerprint(baseItem) !== fingerprint(localItem);

    if (localAdded) {
      summary.hasLocalChanges = true;
      incrementEntity(summary, entityType, (counts) => { counts.added.local += 1; });
    }
    if (localDeleted) {
      summary.hasLocalChanges = true;
      incrementEntity(summary, entityType, (counts) => { counts.deleted.local += 1; });
    }
    if (localModified) {
      summary.hasLocalChanges = true;
      incrementEntity(summary, entityType, (counts) => { counts.modified.local += 1; });
    }

    if (!remote) continue;

    const remoteAdded = !baseItem && Boolean(remoteItem);
    const remoteDeleted = Boolean(baseItem) && !remoteItem;
    const remoteModified = Boolean(baseItem && remoteItem)
      && fingerprint(baseItem) !== fingerprint(remoteItem);

    if (remoteAdded) {
      summary.hasRemoteChanges = true;
      incrementEntity(summary, entityType, (counts) => { counts.added.remote += 1; });
    }
    if (remoteDeleted) {
      summary.hasRemoteChanges = true;
      incrementEntity(summary, entityType, (counts) => { counts.deleted.remote += 1; });
    }
    if (remoteModified) {
      summary.hasRemoteChanges = true;
      incrementEntity(summary, entityType, (counts) => { counts.modified.remote += 1; });
    }

    if (localAdded && remoteAdded && fingerprint(localItem) !== fingerprint(remoteItem)) {
      summary.hasConflicts = true;
      summary.conflicts.push({ entityType, id, kind: 'both-added' });
    } else if (localModified && remoteModified && fingerprint(localItem) !== fingerprint(remoteItem)) {
      summary.hasConflicts = true;
      summary.conflicts.push({ entityType, id, kind: 'both-modified' });
    } else if (localDeleted && remoteModified) {
      summary.hasConflicts = true;
      summary.conflicts.push({ entityType, id, kind: 'local-deleted-remote-modified' });
    } else if (remoteDeleted && localModified) {
      summary.hasConflicts = true;
      summary.conflicts.push({ entityType, id, kind: 'remote-deleted-local-modified' });
    }
  }
}

function recordSettingsChanges(
  summary: SyncChangeSummary,
  base: SyncPayload,
  local: SyncPayload,
  remote?: SyncPayload,
): void {
  const localChanged = fingerprint(local.settings) !== fingerprint(base.settings);
  const remoteChanged = remote !== undefined
    && fingerprint(remote.settings) !== fingerprint(base.settings);

  if (localChanged) {
    summary.hasLocalChanges = true;
    incrementEntity(summary, 'settings', (counts) => { counts.modified.local += 1; });
  }
  if (remoteChanged) {
    summary.hasRemoteChanges = true;
    incrementEntity(summary, 'settings', (counts) => { counts.modified.remote += 1; });
  }
  if (
    localChanged
    && remoteChanged
    && fingerprint(local.settings) !== fingerprint(remote?.settings)
  ) {
    summary.hasConflicts = true;
    summary.conflicts.push({ entityType: 'settings', kind: 'both-modified' });
  }
}

export function summarizeSyncChanges(
  base: SyncPayload | null,
  local: SyncPayload,
  remote?: SyncPayload,
): SyncChangeSummary {
  const reference = base ?? {
    hosts: [],
    keys: [],
    identities: [],
    proxyProfiles: [],
    snippets: [],
    customGroups: [],
    snippetPackages: [],
    portForwardingRules: [],
    groupConfigs: [],
    settings: undefined,
    syncedAt: 0,
  };
  const summary: SyncChangeSummary = {
    hasLocalChanges: false,
    hasRemoteChanges: false,
    hasConflicts: false,
    byEntity: {},
    conflicts: [],
  };

  for (const entityType of CLOUD_SYNC_PAYLOAD_ENTITY_KEYS) {
    recordEntityChanges(
      summary,
      entityType,
      reference[entityType],
      payloadValues(local, entityType, reference),
      remote ? payloadValues(remote, entityType, reference) : undefined,
    );
  }
  recordSettingsChanges(summary, reference, local, remote);

  return summary;
}

export function collectSyncDeletions(
  base: SyncPayload | null,
  current: SyncPayload,
  opts: { deletedAt: number; deviceId?: string },
): SyncDeletionRecord[] {
  if (!base) return [];
  const deletions: SyncDeletionRecord[] = [];

  for (const entityType of CLOUD_SYNC_PAYLOAD_ENTITY_KEYS) {
    const baseItems = entityMap(base[entityType]);
    const currentItems = entityMap(payloadValues(current, entityType, base));
    for (const id of baseItems.keys()) {
      if (!currentItems.has(id)) {
        deletions.push({
          entityType,
          id,
          deletedAt: opts.deletedAt,
          ...(opts.deviceId ? { deviceId: opts.deviceId } : {}),
        });
      }
    }
  }

  return deletions;
}

function mergeDeletionRecords(
  payload: SyncPayload,
  newDeletions: SyncDeletionRecord[],
): SyncDeletionRecord[] {
  const byKey = new Map<string, SyncDeletionRecord>();
  for (const record of [...(payload.syncMeta?.deletions ?? []), ...newDeletions]) {
    const currentItems = entityMap(payload[record.entityType]);
    if (currentItems.has(record.id)) continue;
    const key = `${record.entityType}:${record.id}`;
    const previous = byKey.get(key);
    if (!previous || record.deletedAt >= previous.deletedAt) {
      byKey.set(key, record);
    }
  }
  return Array.from(byKey.values()).sort((a, b) =>
    a.entityType.localeCompare(b.entityType) || a.id.localeCompare(b.id),
  );
}

export function withSyncReliabilityMeta(
  payload: SyncPayload,
  base: SyncPayload | null,
  opts: { deviceId?: string; now?: number } = {},
): SyncPayload {
  const generatedAt = opts.now ?? Date.now();
  const changeSummary = summarizeSyncChanges(base, payload);
  const deletions = mergeDeletionRecords(
    payload,
    collectSyncDeletions(base, payload, {
      deletedAt: generatedAt,
      ...(opts.deviceId ? { deviceId: opts.deviceId } : {}),
    }),
  );
  const meta: SyncReliabilityMeta = {
    schemaVersion: 1,
    generatedAt,
    ...(opts.deviceId ? { deviceId: opts.deviceId } : {}),
    ...(base?.syncedAt ? { baseSyncedAt: base.syncedAt } : {}),
    localChanged: changeSummary.hasLocalChanges,
    deletions,
    changeSummary,
  };

  return {
    ...payload,
    syncMeta: meta,
  };
}

export function carryForwardSyncDeletions(
  payload: SyncPayload,
  sources: SyncPayload[],
  opts: { generatedAt?: number; deviceId?: string } = {},
): SyncPayload {
  const sourceDeletions = sources.flatMap((source) => source.syncMeta?.deletions ?? []);
  const deletions = mergeDeletionRecords(
    {
      ...payload,
      syncMeta: {
        schemaVersion: 1,
        generatedAt: opts.generatedAt ?? Date.now(),
        ...(opts.deviceId ? { deviceId: opts.deviceId } : {}),
        localChanged: false,
        deletions: sourceDeletions,
        changeSummary: summarizeSyncChanges(null, payload),
      },
    },
    [],
  );

  if (deletions.length === 0) return payload;

  return {
    ...payload,
    syncMeta: {
      schemaVersion: 1,
      generatedAt: opts.generatedAt ?? Date.now(),
      ...(opts.deviceId ? { deviceId: opts.deviceId } : {}),
      localChanged: false,
      deletions,
      changeSummary: summarizeSyncChanges(null, payload),
    },
  };
}

export function getDeletedEntityIds(
  payload: SyncPayload,
  entityType: CloudSyncPayloadEntityKey,
): Set<string> {
  return new Set(
    (payload.syncMeta?.deletions ?? [])
      .filter((record) => record.entityType === entityType)
      .map((record) => record.id),
  );
}

import type { TerminalSession, TerminalSettings } from "./models/terminal";

/** Compile-time kill switch for terminal hibernate (Settings > Terminal still controls user default). */
export const TERMINAL_HIBERNATE_ENABLED = true;

/** Default delay before hibernating a hidden tab (seconds). */
export const TERMINAL_HIBERNATE_DELAY_SEC_DEFAULT = 5;

export const TERMINAL_HIBERNATE_DELAY_SEC_MIN = 5;

export const TERMINAL_HIBERNATE_DELAY_SEC_MAX = 600;

/** Default delay in milliseconds (legacy constant for tests). */
export const TERMINAL_HIBERNATE_DELAY_MS = TERMINAL_HIBERNATE_DELAY_SEC_DEFAULT * 1000;

export function normalizeHibernateHiddenTabsDelaySec(value: unknown): number {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return TERMINAL_HIBERNATE_DELAY_SEC_DEFAULT;
  }
  return Math.min(
    TERMINAL_HIBERNATE_DELAY_SEC_MAX,
    Math.max(TERMINAL_HIBERNATE_DELAY_SEC_MIN, Math.round(value)),
  );
}

export function resolveTerminalHibernateDelayMs(
  settings?: Pick<TerminalSettings, "hibernateHiddenTabsDelaySec"> | null,
): number {
  return normalizeHibernateHiddenTabsDelaySec(settings?.hibernateHiddenTabsDelaySec) * 1000;
}

export function resolveTerminalHibernateEnabled(
  settings?: Pick<TerminalSettings, "hibernateHiddenTabs"> | null,
): boolean {
  if (!TERMINAL_HIBERNATE_ENABLED) return false;
  return settings?.hibernateHiddenTabs === true;
}

export function resolveTerminalHibernateEnabledForProtocol(
  settings: Pick<TerminalSettings, "hibernateHiddenTabs"> | null | undefined,
  protocol: string | null | undefined,
): boolean {
  return protocol !== "local" && resolveTerminalHibernateEnabled(settings);
}

/** Hidden connected and ended remote terminals can both release their xterm runtime. */
export function canHibernateTerminalRuntimeStatus(
  status: TerminalSession["status"],
): boolean {
  return status === "connected" || status === "disconnected";
}

export function canHibernateTerminalRuntimeSession(
  status: TerminalSession["status"],
  backendSessionId: string | null | undefined,
): boolean {
  if (!canHibernateTerminalRuntimeStatus(status)) return false;
  return status === "disconnected" || Boolean(backendSessionId);
}

export function shouldKeepTerminalBackgroundWorkActive(
  settings: Pick<TerminalSettings, "hibernateHiddenTabs"> | null | undefined,
  protocol: string | null | undefined,
  isVisible: boolean,
): boolean {
  return isVisible || !resolveTerminalHibernateEnabledForProtocol(settings, protocol);
}

/** Block hibernate while a file transfer or drag-drop session is in progress. */
export function isTerminalFileTransferActive(options: {
  zmodemActive: boolean;
  ymodemInProgress: boolean;
  isDraggingOver: boolean;
}): boolean {
  return options.zmodemActive || options.ymodemInProgress || options.isDraggingOver;
}

/** Lines kept when snapshotting xterm scrollback before hibernate. */
export const TERMINAL_HIBERNATE_SNAPSHOT_MAX_LINES = 3_000;

/** Default chunk size for replaying hibernate snapshots without blocking the main thread. */
export const TERMINAL_HIBERNATE_REPLAY_CHUNK_BYTES_DEFAULT = 16 * 1024;

export const TERMINAL_HIBERNATE_REPLAY_CHUNK_BYTES_MIN = 4 * 1024;

export const TERMINAL_HIBERNATE_REPLAY_CHUNK_BYTES_MAX = 64 * 1024;

/** Hidden tabs whose xterm runtime is kept alive (WebGL suspended) before full hibernate. */
export const TERMINAL_HIBERNATE_KEEP_RENDERER_COUNT_DEFAULT = 2;

export const TERMINAL_HIBERNATE_KEEP_RENDERER_COUNT_MIN = 0;

export const TERMINAL_HIBERNATE_KEEP_RENDERER_COUNT_MAX = 12;

/** Max chars buffered in renderer while xterm is hibernated (post-snapshot output). */
export const TERMINAL_HIBERNATE_BUFFER_MAX_CHARS = 512 * 1024;

export function capHibernateBuffer(buffer: string, maxChars = TERMINAL_HIBERNATE_BUFFER_MAX_CHARS): string {
  if (buffer.length <= maxChars) return buffer;
  return buffer.slice(buffer.length - maxChars);
}

export function capHibernateBufferByLines(text: string, maxLines: number): string {
  if (maxLines <= 0 || text.length === 0) return text;
  const lines = text.split("\n");
  if (lines.length <= maxLines) return text;
  return lines.slice(lines.length - maxLines).join("\n");
}

export function normalizeHibernateReplayChunkBytes(value: unknown): number {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return TERMINAL_HIBERNATE_REPLAY_CHUNK_BYTES_DEFAULT;
  }
  return Math.min(
    TERMINAL_HIBERNATE_REPLAY_CHUNK_BYTES_MAX,
    Math.max(TERMINAL_HIBERNATE_REPLAY_CHUNK_BYTES_MIN, Math.round(value)),
  );
}

export function normalizeHibernateKeepRendererCount(value: unknown): number {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return TERMINAL_HIBERNATE_KEEP_RENDERER_COUNT_DEFAULT;
  }
  return Math.min(
    TERMINAL_HIBERNATE_KEEP_RENDERER_COUNT_MAX,
    Math.max(TERMINAL_HIBERNATE_KEEP_RENDERER_COUNT_MIN, Math.round(value)),
  );
}

export function resolveTerminalHibernateReplayChunkBytes(
  settings?: Pick<TerminalSettings, "hibernateReplayChunkBytes"> | null,
): number {
  return normalizeHibernateReplayChunkBytes(settings?.hibernateReplayChunkBytes);
}

export function resolveHibernateKeepRendererCount(
  settings?: Pick<TerminalSettings, "hibernateKeepRendererCount"> | null,
): number {
  return normalizeHibernateKeepRendererCount(settings?.hibernateKeepRendererCount);
}

export function resolveHibernateSkipAltScreen(
  settings?: Pick<TerminalSettings, "hibernateSkipAltScreen"> | null,
): boolean {
  return settings?.hibernateSkipAltScreen !== false;
}

export function resolveHibernatePreferWasmSerialize(
  settings?: Pick<TerminalSettings, "hibernatePreferWasmSerialize"> | null,
): boolean {
  return settings?.hibernatePreferWasmSerialize === true;
}

export function shouldSkipHibernateForAltScreen(
  alternateScreen: boolean,
  settings?: Pick<TerminalSettings, "hibernateSkipAltScreen"> | null,
): boolean {
  return alternateScreen && resolveHibernateSkipAltScreen(settings);
}

/** Snapshot + buffered output to replay when recreating xterm after hibernate. */
export type TerminalHibernateWakePayload = {
  /** Full serialized terminal state -- preferred wake history (coherent ANSI). */
  snapshot: string;
  /** Visible viewport rows; used with scrollback only when snapshot is empty. */
  viewportSnapshot?: string;
  /** Older scrollback rows; used with viewport only when snapshot is empty. */
  scrollbackSnapshot?: string;
  pendingBuffer: string;
  /** True when the pane was hibernated while a full-screen app owned the alt buffer. */
  alternateScreen: boolean;
};

import type { TerminalSettings } from "./models/terminal";

/**
 * Inline raster image output (Kitty graphics, SIXEL, iTerm IIP) rendered by
 * `@xterm/addon-image`. The addon keeps decoded bitmaps outside the terminal
 * buffer, so every limit here is a memory guard rather than a cosmetic option:
 *
 * - `storageLimit` caps the FIFO image cache of a single terminal (MB, RGBA8888).
 * - `pixelLimit` caps a single decoded image; the decoder holds up to two pixel
 *   buffers of that size while working, so 4 bytes * pixels * 2 is the transient
 *   peak per decoding terminal.
 * - the sequence limit caps the raw escape-sequence payload before decoding, so
 *   an oversized or corrupt sequence is rejected before it allocates anything.
 */

/** Compile-time kill switch for inline terminal images. */
export const TERMINAL_INLINE_IMAGES_ENABLED = true;

/** Per-terminal image cache size in MB. */
export const TERMINAL_INLINE_IMAGE_STORAGE_LIMIT_MB_DEFAULT = 128;

export const TERMINAL_INLINE_IMAGE_STORAGE_LIMIT_MB_MIN = 8;

export const TERMINAL_INLINE_IMAGE_STORAGE_LIMIT_MB_MAX = 512;

/** Largest single decoded image, in megapixels (16 MP == 4096 x 4096). */
export const TERMINAL_INLINE_IMAGE_MAX_MEGAPIXELS_DEFAULT = 16;

export const TERMINAL_INLINE_IMAGE_MAX_MEGAPIXELS_MIN = 1;

export const TERMINAL_INLINE_IMAGE_MAX_MEGAPIXELS_MAX = 64;

/** Largest single image escape sequence, in MB, before decoding is attempted. */
export const TERMINAL_INLINE_IMAGE_SEQUENCE_LIMIT_MB_DEFAULT = 24;

export const TERMINAL_INLINE_IMAGE_SEQUENCE_LIMIT_MB_MIN = 1;

export const TERMINAL_INLINE_IMAGE_SEQUENCE_LIMIT_MB_MAX = 64;

const BYTES_PER_MB = 1024 * 1024;

const PIXELS_PER_MEGAPIXEL = 1024 * 1024;

const clampInteger = (value: unknown, min: number, max: number, fallback: number): number => {
  if (typeof value !== "number" || !Number.isFinite(value)) return fallback;
  return Math.min(max, Math.max(min, Math.round(value)));
};

export function normalizeInlineImageStorageLimitMb(value: unknown): number {
  return clampInteger(
    value,
    TERMINAL_INLINE_IMAGE_STORAGE_LIMIT_MB_MIN,
    TERMINAL_INLINE_IMAGE_STORAGE_LIMIT_MB_MAX,
    TERMINAL_INLINE_IMAGE_STORAGE_LIMIT_MB_DEFAULT,
  );
}

export function normalizeInlineImageMaxMegapixels(value: unknown): number {
  return clampInteger(
    value,
    TERMINAL_INLINE_IMAGE_MAX_MEGAPIXELS_MIN,
    TERMINAL_INLINE_IMAGE_MAX_MEGAPIXELS_MAX,
    TERMINAL_INLINE_IMAGE_MAX_MEGAPIXELS_DEFAULT,
  );
}

export function normalizeInlineImageSequenceLimitMb(value: unknown): number {
  return clampInteger(
    value,
    TERMINAL_INLINE_IMAGE_SEQUENCE_LIMIT_MB_MIN,
    TERMINAL_INLINE_IMAGE_SEQUENCE_LIMIT_MB_MAX,
    TERMINAL_INLINE_IMAGE_SEQUENCE_LIMIT_MB_DEFAULT,
  );
}

export type TerminalInlineImageSettings = Pick<
  TerminalSettings,
  | "inlineImagesEnabled"
  | "inlineImageKittyEnabled"
  | "inlineImageSixelEnabled"
  | "inlineImageIipEnabled"
  | "inlineImageStorageLimitMb"
  | "inlineImageMaxMegapixels"
  | "inlineImageSequenceLimitMb"
>;

/**
 * Structural mirror of `IImageAddonOptions` from `@xterm/addon-image`. Declared
 * here so the domain layer stays free of renderer dependencies; the runtime
 * passes the result straight into the addon constructor.
 */
export type TerminalInlineImageAddonOptions = {
  enableSizeReports: boolean;
  pixelLimit: number;
  storageLimit: number;
  showPlaceholder: boolean;
  sixelSupport: boolean;
  sixelSizeLimit: number;
  iipSupport: boolean;
  iipSizeLimit: number;
  kittySupport: boolean;
  kittySizeLimit: number;
};

export function resolveTerminalInlineImagesEnabled(
  settings?: Partial<TerminalInlineImageSettings> | null,
): boolean {
  if (!TERMINAL_INLINE_IMAGES_ENABLED) return false;
  if (settings?.inlineImagesEnabled !== true) return false;
  return (
    settings.inlineImageKittyEnabled === true
    || settings.inlineImageSixelEnabled === true
    || settings.inlineImageIipEnabled === true
  );
}

/**
 * Build the addon options for a terminal, or `null` when inline images are off
 * (master switch, or every protocol disabled). A `null` result means the addon
 * must not be loaded at all, so the terminal keeps advertising no graphics
 * capability to the remote side.
 */
export function resolveTerminalInlineImageAddonOptions(
  settings?: Partial<TerminalInlineImageSettings> | null,
): TerminalInlineImageAddonOptions | null {
  if (!resolveTerminalInlineImagesEnabled(settings)) return null;
  const sequenceLimitBytes =
    normalizeInlineImageSequenceLimitMb(settings?.inlineImageSequenceLimitMb) * BYTES_PER_MB;
  return {
    // Image producers need CSI 14/16/18 t to size their output to the grid.
    enableSizeReports: true,
    pixelLimit:
      normalizeInlineImageMaxMegapixels(settings?.inlineImageMaxMegapixels) * PIXELS_PER_MEGAPIXEL,
    storageLimit: normalizeInlineImageStorageLimitMb(settings?.inlineImageStorageLimitMb),
    showPlaceholder: true,
    sixelSupport: settings?.inlineImageSixelEnabled === true,
    sixelSizeLimit: sequenceLimitBytes,
    iipSupport: settings?.inlineImageIipEnabled === true,
    iipSizeLimit: sequenceLimitBytes,
    kittySupport: settings?.inlineImageKittyEnabled === true,
    kittySizeLimit: sequenceLimitBytes,
  };
}

